/*
 * Site-wide animated background, following the theme (html[data-theme]).
 *   Light: "波纹 / Waves" by ezydong on 21st.dev  (https://21st.dev/@ezydong/components/shader-59f0538a)
 *   Dark:  "a Shader / Mesh Gradient" by thiienu on 21st.dev (https://21st.dev/@thiienu/components/a-shader),
 *          adapted from Paper Shaders (Apache-2.0).
 * Both were generated by the 21st.dev Shader Builder; this is a plain-JS port of the two React components
 * (same shader, same settings). One fixed WebGL canvas behind the whole page; it switches shader when the
 * theme toggle changes data-theme. Pauses while the tab is hidden.
 */
(function () {
  "use strict";
  if (window.__paShaderBg) return;
  window.__paShaderBg = true;

  var VERT = "attribute vec2 a_position;\nvoid main() {\n  gl_Position = vec4(a_position, 0.0, 1.0);\n}";

  // Shared part of the Shader Builder fragment shader (everything except shade()).
  var HEAD = [
    "#ifdef GL_FRAGMENT_PRECISION_HIGH",
    "precision highp float;",
    "#else",
    "precision mediump float;",
    "#endif",
    "uniform vec3 u_colors[8];",
    "uniform vec4 u_scene; uniform vec4 u_shape; uniform vec4 u_surface; uniform vec4 u_finish;",
    "uniform vec4 u_transform; uniform vec4 u_space; uniform vec4 u_cursor;",
    "#define u_resolution u_scene.xy",
    "#define u_time u_scene.z",
    "#define u_colorCount u_scene.w",
    "#define u_scale u_shape.x",
    "#define u_intensity u_shape.y",
    "#define u_paramA u_shape.z",
    "#define u_warp u_shape.w",
    "#define u_detail u_surface.x",
    "#define u_contrast u_surface.y",
    "#define u_brightness u_surface.z",
    "#define u_saturation u_surface.w",
    "#define u_hue u_finish.x",
    "#define u_vignette u_finish.y",
    "#define u_blur u_finish.z",
    "#define u_grain u_finish.w",
    "#ifdef GL_FRAGMENT_PRECISION_HIGH",
    "#define u_seed u_transform.x",
    "#else",
    "#define u_seed mod(u_transform.x, 31.0)",
    "#endif",
    "#define u_rotate u_transform.y",
    "#define u_drift u_transform.z",
    "#define u_oklab u_transform.w",
    "#define u_offset u_space.xy",
    "#define u_mouse u_space.zw",
    "#define u_cursorPresence u_cursor.x",
    "#define u_cursorEffect u_cursor.y",
    "#define u_cursorStrength u_cursor.z",
    "#define u_cursorRadius u_cursor.w",
    "float hash21(vec2 p) {",
    "#ifndef GL_FRAGMENT_PRECISION_HIGH",
    "  p = mod(p, 31.0);",
    "#endif",
    "  p = fract(p * vec2(234.34, 435.345));",
    "  p += dot(p, p + 34.23);",
    "  return fract(p.x * p.y);",
    "}",
    "float grainHash(vec2 p) {",
    "  vec3 p3 = fract(vec3(p.xyx) * 0.1031);",
    "  p3 += dot(p3, p3.yzx + 33.33);",
    "  return fract((p3.x + p3.y) * p3.z);",
    "}",
    "float noise(vec2 p) {",
    "  vec2 i = floor(p);",
    "  vec2 f = fract(p);",
    "  vec2 u = f * f * (3.0 - 2.0 * f);",
    "  return mix(mix(hash21(i), hash21(i + vec2(1.0, 0.0)), u.x), mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), u.x), u.y);",
    "}",
    "float fbm(vec2 p) {",
    "  float v = 0.0;",
    "  float a = 0.5;",
    "  for (int i = 0; i < 5; i++) {",
    "    v += a * noise(p);",
    "    p = p * 2.03 + vec2(17.0, 9.2);",
    "    a *= 0.5;",
    "  }",
    "  return v;",
    "}",
    "vec3 srgbToLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c)); }",
    "vec3 linearToSrgb(vec3 c) { return mix(c * 12.92, 1.055 * pow(max(c, vec3(0.0)), vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c)); }",
    "vec3 linToOklab(vec3 c) {",
    "  float l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;",
    "  float m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;",
    "  float s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;",
    "  l = pow(max(l, 0.0), 1.0 / 3.0); m = pow(max(m, 0.0), 1.0 / 3.0); s = pow(max(s, 0.0), 1.0 / 3.0);",
    "  return vec3(0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s, 1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s, 0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s);",
    "}",
    "vec3 oklabToLin(vec3 c) {",
    "  float l = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;",
    "  float m = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;",
    "  float s = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;",
    "  l = l * l * l; m = m * m * m; s = s * s * s;",
    "  return vec3(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);",
    "}",
    "vec3 mixColour(vec3 a, vec3 b, float t) {",
    "  if (u_oklab > 0.5) {",
    "    vec3 la = linToOklab(srgbToLinear(a));",
    "    vec3 lb = linToOklab(srgbToLinear(b));",
    "    return clamp(linearToSrgb(oklabToLin(mix(la, lb, t))), 0.0, 1.0);",
    "  }",
    "  return mix(a, b, t);",
    "}",
    "vec3 palette(float x) {",
    "  float n = max(u_colorCount - 1.0, 1.0);",
    "  float f = clamp(x, 0.0, 1.0) * n;",
    "  vec3 col = u_colors[0];",
    "  for (int i = 0; i < 7; i++) {",
    "    if (float(i) < n) col = mixColour(col, u_colors[i + 1], smoothstep(0.0, 1.0, clamp(f - float(i), 0.0, 1.0)));",
    "  }",
    "  return col;",
    "}",
    "vec3 hueRotate(vec3 col, float a) {",
    "  const mat3 toYIQ = mat3(0.299, 0.596, 0.211, 0.587, -0.274, -0.523, 0.114, -0.322, 0.312);",
    "  const mat3 toRGB = mat3(1.0, 1.0, 1.0, 0.956, -0.272, -1.106, 0.621, -0.647, 1.703);",
    "  vec3 yiq = toYIQ * col;",
    "  float ca = cos(a), sa = sin(a);",
    "  yiq = vec3(yiq.x, yiq.y * ca - yiq.z * sa, yiq.y * sa + yiq.z * ca);",
    "  return toRGB * yiq;",
    "}"
  ].join("\n");

  var MAIN = [
    "void main() {",
    "  vec2 uv = gl_FragCoord.xy / u_resolution.xy;",
    "  vec2 screenUv = uv;",
    "  vec2 p = (gl_FragCoord.xy - 0.5 * u_resolution.xy) / min(u_resolution.x, u_resolution.y);",
    "  float cursorMask = 0.0;",
    "  if (u_cursorPresence > 0.001) {",
    "    vec2 cursor = (0.5 * u_mouse * u_resolution.xy) / min(u_resolution.x, u_resolution.y);",
    "    vec2 cursorDelta = p - cursor;",
    "    if (u_cursorEffect < 0.5) {",
    "      p += cursor * u_cursorPresence * u_cursorStrength * 0.55;",
    "    } else {",
    "      float cursorDistance = length(cursorDelta);",
    "      vec2 cursorDirection = cursorDelta / max(cursorDistance, 0.0001);",
    "      cursorMask = u_cursorPresence * (1.0 - smoothstep(0.0, u_cursorRadius, cursorDistance));",
    "      if (u_cursorEffect < 1.5) {",
    "        p -= cursorDirection * cursorMask * u_cursorStrength * 0.24;",
    "      } else if (u_cursorEffect < 2.5) {",
    "        float cursorAngle = cursorMask * u_cursorStrength * 2.2;",
    "        float cc = cos(cursorAngle), cs = sin(cursorAngle);",
    "        p = cursor + mat2(cc, -cs, cs, cc) * cursorDelta;",
    "      } else if (u_cursorEffect < 3.5) {",
    "        float ripple = sin(cursorDistance / max(u_cursorRadius, 0.001) * 18.0 - u_time * 5.0);",
    "        p -= cursorDirection * ripple * cursorMask * u_cursorStrength * 0.07;",
    "      }",
    "    }",
    "  }",
    "  uv = p * min(u_resolution.x, u_resolution.y) / u_resolution.xy + 0.5;",
    "  p *= u_scale;",
    "  if (abs(u_rotate) > 0.0001) {",
    "    float cr = cos(u_rotate), sr = sin(u_rotate);",
    "    p = mat2(cr, -sr, sr, cr) * p;",
    "  }",
    "  p += u_offset;",
    "  if (u_drift > 0.0001) p += u_drift * vec2(sin(u_time * 0.31), cos(u_time * 0.23));",
    "  if (u_warp > 0.0) {",
    "    p += u_warp * (vec2(fbm(p * u_detail + u_seed), fbm(p * u_detail + vec2(5.2, 1.3))) - 0.5);",
    "  }",
    "  vec3 col;",
    "  if (u_blur > 0.0) {",
    "    float e = u_blur;",
    "    float pe = e * u_scale;",
    "    vec2 uvE = vec2(e) * min(u_resolution.x, u_resolution.y) / u_resolution.xy;",
    "    col  = shade(uv, p, u_time) * 0.36;",
    "    col += shade(uv + vec2(uvE.x, 0.0), p + vec2(pe, 0.0), u_time) * 0.16;",
    "    col += shade(uv - vec2(uvE.x, 0.0), p - vec2(pe, 0.0), u_time) * 0.16;",
    "    col += shade(uv + vec2(0.0, uvE.y), p + vec2(0.0, pe), u_time) * 0.16;",
    "    col += shade(uv - vec2(0.0, uvE.y), p - vec2(0.0, pe), u_time) * 0.16;",
    "  } else {",
    "    col = shade(uv, p, u_time);",
    "  }",
    "  if (abs(u_contrast - 1.0) > 0.0001) col = (col - 0.5) * u_contrast + 0.5;",
    "  if (abs(u_saturation - 1.0) > 0.0001) {",
    "    float luma = dot(col, vec3(0.299, 0.587, 0.114));",
    "    col = mix(vec3(luma), col, u_saturation);",
    "  }",
    "  if (abs(u_hue) > 0.0001) col = hueRotate(col, u_hue);",
    "  if (abs(u_brightness) > 0.0001) col += u_brightness;",
    "  if (u_vignette > 0.0001) {",
    "    float vd = length(screenUv - 0.5) * 1.41421356;",
    "    col *= 1.0 - u_vignette * smoothstep(0.35, 1.0, vd);",
    "  }",
    "  if (u_cursorPresence > 0.001 && u_cursorEffect > 3.5) col += (vec3(0.18) + col * 0.12) * cursorMask * u_cursorStrength;",
    "  if (u_grain > 0.0001) col += (grainHash(gl_FragCoord.xy + vec2(u_seed * 17.0, u_seed * 31.0)) - 0.5) * u_grain;",
    "  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);",
    "}"
  ].join("\n");

  // Light: "Waves" (ezydong).
  var SHADE_WAVES = [
    "vec3 shade(vec2 uv, vec2 p, float t) {",
    "  float y = uv.y + sin(uv.x * (3.0 + u_intensity * 9.0) + t * 0.8) * 0.08 + (fbm(p * 2.0 + t * 0.1) - 0.5) * u_intensity * 0.6;",
    "  return palette(y);",
    "}"
  ].join("\n");

  // Dark: "Mesh Gradient" (thiienu).
  var SHADE_MESH = [
    "vec3 shade(vec2 uv, vec2 p, float t) {",
    "  vec3 color = u_colors[0] * 0.16;",
    "  float weight = 0.16;",
    "  for (int i = 0; i < 8; i++) {",
    "    if (float(i) >= u_colorCount) break;",
    "    float fi = float(i);",
    "    vec2 center = vec2(sin(fi * 2.17 + t * 0.13 + u_seed), cos(fi * 1.63 - t * 0.11)) * (0.22 + u_intensity * 0.62);",
    "    float falloff = mix(12.0, 2.4, u_paramA);",
    "    float influence = exp(-dot(p - center, p - center) * falloff);",
    "    color += u_colors[i] * influence;",
    "    weight += influence;",
    "  }",
    "  return color / weight;",
    "}"
  ].join("\n");

  var PRESETS = {
    light: {
      shade: SHADE_WAVES,
      colors: [[0.09411764705882353, 0.27058823529411763, 0.3411764705882353], [0, 0.4980392156862745, 0.6784313725490196], [0.3411764705882353, 0.6980392156862745, 0.796078431372549], [0.9176470588235294, 0.9764705882352941, 1], [0, 0.4980392156862745, 0.6784313725490196], [0, 0.4980392156862745, 0.6784313725490196], [0, 0.4980392156862745, 0.6784313725490196], [0, 0.4980392156862745, 0.6784313725490196]],
      colorCount: 5, scale: 1.880, intensity: 0.430, paramA: 0.710, warp: 0.330, detail: 1.728, contrast: 0.915, brightness: -0.030,
      saturation: 1.280, hue: 0.0000, vignette: 0.000, blur: 0.0000, grain: 0.000, seed: 3165.0, rotate: 3.4034, offsetX: 0.100,
      offsetY: -0.250, drift: 0.156, cursorEnabled: true, cursorEffect: 2.0, cursorStrength: 0.040, cursorRadius: 0.412, oklab: 0.0, timeScale: 0.746
    },
    dark: {
      shade: SHADE_MESH,
      colors: [[0.07058823529411765, 0.050980392156862744, 0.19215686274509805], [0.4235294117647059, 0.2980392156862745, 0.9450980392156862], [0.9372549019607843, 0.36470588235294116, 0.6588235294117647], [1, 0.8196078431372549, 0.4], [1, 0.8196078431372549, 0.4], [1, 0.8196078431372549, 0.4], [1, 0.8196078431372549, 0.4], [1, 0.8196078431372549, 0.4]],
      colorCount: 4, scale: 1.260, intensity: 0.350, paramA: 0.280, warp: 0.000, detail: 1.824, contrast: 1.005, brightness: -0.030,
      saturation: 1.480, hue: 0.5236, vignette: 0.280, blur: 0.0080, grain: 0.045, seed: 4309.0, rotate: 0.0000, offsetX: -0.240,
      offsetY: -0.030, drift: 0.156, cursorEnabled: false, cursorEffect: 0.0, cursorStrength: 0.850, cursorRadius: 0.630, oklab: 0.0, timeScale: -0.575
    }
  };

  function currentTheme() {
    return document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark";
  }

  var canvas = document.createElement("canvas");
  canvas.id = "pa-shader-bg";
  canvas.setAttribute("aria-hidden", "true");
  var gl = canvas.getContext("webgl", { antialias: false });
  if (!gl) return; // no WebGL: the layouts keep their plain background colour

  var buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);

  var programs = {};
  function programFor(theme) {
    if (programs[theme]) return programs[theme];
    var P = PRESETS[theme];
    function compile(type, src) {
      var s = gl.createShader(type);
      gl.shaderSource(s, src);
      gl.compileShader(s);
      return s;
    }
    var program = gl.createProgram();
    var vs = compile(gl.VERTEX_SHADER, VERT);
    var fs = compile(gl.FRAGMENT_SHADER, HEAD + "\n" + P.shade + "\n" + MAIN);
    gl.attachShader(program, vs);
    gl.attachShader(program, fs);
    gl.linkProgram(program);
    gl.deleteShader(vs);
    gl.deleteShader(fs);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
    var uni = {};
    ["u_colors", "u_scene", "u_shape", "u_surface", "u_finish", "u_transform", "u_space", "u_cursor"].forEach(function (n) {
      uni[n] = gl.getUniformLocation(program, n);
    });
    programs[theme] = { program: program, uni: uni, P: P, loc: gl.getAttribLocation(program, "a_position") };
    return programs[theme];
  }

  var active = null;
  function useTheme(theme) {
    var prog = programFor(theme);
    if (!prog) return;
    active = prog;
    var P = prog.P, u = prog.uni;
    gl.useProgram(prog.program);
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.enableVertexAttribArray(prog.loc);
    gl.vertexAttribPointer(prog.loc, 2, gl.FLOAT, false, 0, 0);
    var flat = [];
    P.colors.forEach(function (c) { flat.push(c[0], c[1], c[2]); });
    gl.uniform3fv(u.u_colors, new Float32Array(flat));
    gl.uniform4f(u.u_shape, P.scale, P.intensity, P.paramA, P.warp);
    gl.uniform4f(u.u_surface, P.detail, P.contrast, P.brightness, P.saturation);
    gl.uniform4f(u.u_finish, P.hue, P.vignette, P.blur, P.grain);
    gl.uniform4f(u.u_transform, P.seed, P.rotate, P.drift, P.oklab);
    document.documentElement.classList.toggle("pa-bg-light", theme === "light");
    document.documentElement.classList.toggle("pa-bg-dark", theme === "dark");
    requestRender();
  }

  // Pointer (only the light preset reacts to it: a gentle swirl under the cursor).
  var targetX = 0, targetY = 0, targetPresence = 0, mouseX = 0, mouseY = 0, cursorPresence = 0;
  window.addEventListener("pointermove", function (e) {
    var nx = (e.clientX / window.innerWidth) * 2 - 1;
    var ny = -((e.clientY / window.innerHeight) * 2 - 1);
    if (targetPresence === 0 && cursorPresence < 0.01) { mouseX = nx; mouseY = ny; }
    targetX = nx; targetY = ny; targetPresence = 1;
    requestRender();
  }, { passive: true });
  function leave() { targetPresence = 0; requestRender(); }
  window.addEventListener("blur", leave);
  document.documentElement.addEventListener("pointerleave", leave);

  function resize() {
    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    var rawW = Math.max(1, Math.round(window.innerWidth * dpr));
    var rawH = Math.max(1, Math.round(window.innerHeight * dpr));
    // Cap the pixel count (as the original does) so big screens stay smooth.
    var scale = Math.min(1, Math.sqrt(2000000 / Math.max(1, rawW * rawH)));
    var w = Math.max(1, Math.round(rawW * scale)), h = Math.max(1, Math.round(rawH * scale));
    if (canvas.width !== w || canvas.height !== h) {
      canvas.width = w;
      canvas.height = h;
      gl.viewport(0, 0, w, h);
    }
  }

  var raf = 0, lastNow = null, start = performance.now();
  var visible = document.visibilityState === "visible";
  function requestRender() {
    if (visible && raf === 0) raf = requestAnimationFrame(render);
  }
  function render(now) {
    raf = 0;
    if (!visible || !active) return;
    var dt = lastNow === null ? 0 : Math.min((now - lastNow) / 1000, 0.1);
    lastNow = now;
    var follow = 1 - Math.exp(-12 * dt);
    mouseX += (targetX - mouseX) * follow;
    mouseY += (targetY - mouseY) * follow;
    cursorPresence += (targetPresence - cursorPresence) * follow;
    resize();
    var P = active.P, u = active.uni;
    gl.uniform4f(u.u_scene, canvas.width, canvas.height, ((now - start) / 1000) * P.timeScale, P.colorCount);
    gl.uniform4f(u.u_space, P.offsetX, P.offsetY, mouseX, mouseY);
    gl.uniform4f(u.u_cursor, P.cursorEnabled ? cursorPresence : 0, P.cursorEffect, P.cursorStrength, P.cursorRadius);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    requestRender();
  }
  document.addEventListener("visibilitychange", function () {
    visible = document.visibilityState === "visible";
    if (visible) { lastNow = null; requestRender(); }
    else if (raf) { cancelAnimationFrame(raf); raf = 0; }
  });
  window.addEventListener("resize", requestRender);

  // Follow the theme toggle.
  new MutationObserver(function () {
    var t = currentTheme();
    if (!active || active.P !== PRESETS[t]) useTheme(t);
  }).observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });

  function mount() {
    document.body.insertBefore(canvas, document.body.firstChild);
    document.documentElement.classList.add("pa-has-shader-bg");
    useTheme(currentTheme());
  }
  if (document.body) mount();
  else document.addEventListener("DOMContentLoaded", mount);
})();
